/**
 * The footer reveal's measure on every page of the frontend base layout: the
 * sticky footer needs its own height, as --foot-h on <html>, so a footer taller
 * than the window still scrolls into full view. Also stamps data-scrolled on
 * <html> once the page has scrolled past SCROLLED_AT pixels.
 */
const SCROLLED_AT = 40;

export default async () => {
  const $root = document.documentElement;
  const markScrolled = () => $root.toggleAttribute('data-scrolled', window.scrollY > SCROLLED_AT);

  window.addEventListener('scroll', markScrolled, { passive: true });
  markScrolled();

  // The preview page turns the footer off, so it has nothing to measure
  const $footer = document.querySelector('.explorer-foot');

  if (!$footer) {
    return;
  }

  new ResizeObserver(() => {
    $root.style.setProperty('--foot-h', `${$footer.offsetHeight}px`);
  }).observe($footer);
};
